+fn structural_chars(source: &str) -> Vec<char> {
+    let mut chars = source.chars().collect::<Vec<_>>();
+    let mut in_string = false;
+    let mut in_comment = false;
+    let mut escaped = false;
+    let mut index = 0;
+    while index < chars.len() {
+        let ch = chars[index];
+        if in_comment {
+            if ch == '\n' {
+                in_comment = false;
+            } else {
+                chars[index] = ' ';
+            }
+        } else if in_string {
+            chars[index] = ' ';
+            if escaped {
+                escaped = false;
+            } else if ch == '\\' {
+                escaped = true;
+            } else if ch == '"' {
+                in_string = false;
+            }
+        } else if ch == '"' {
+            in_string = true;
+            chars[index] = ' ';
+        } else if ch == '/' && chars.get(index + 1) == Some(&'/') {
+            in_comment = true;
+            chars[index] = ' ';
+        }
+        index += 1;
+    }
+    chars
+}
