@@ -0,0 +1,41 @@
+// SPDX-License-Identifier: Apache-2.0
+
+use std::process::Command;
+
+use serde_json::Value;
+
+#[test]
+fn reviewgraphen_generated_regression() {
+    let directory = std::env::temp_dir().join(format!(
+        "fslc-ai-commented-block-{}",
+        std::process::id()
+    ));
+    std::fs::create_dir_all(&directory).expect("create fixture directory");
+    let project = directory.join("commented-project.fsl");
+    std::fs::write(
+        &project,
+        r#"// statistical_property Phantom {
+dataset Evaluation {
+  source "records.jsonl";
+}
+statistical_property Accuracy {
+  target Assistant
+  dataset Evaluation
+  evaluator Judge
+  require min_samples >= 1
+}
+"#,
+    )
+    .expect("write project");
+
+    let output = Command::new(env!("CARGO_BIN_EXE_fslc"))
+        .args(["ai", "check", project.to_str().expect("UTF-8 path")])
+        .output()
+        .expect("run fslc");
+    let _ = std::fs::remove_dir_all(&directory);
+    assert!(output.status.success(), "{}", String::from_utf8_lossy(&output.stdout));
+    let value: Value = serde_json::from_slice(&output.stdout).expect("JSON output");
+    assert_eq!(value["result"], "ai_project_analyzed");
+    assert_eq!(
+        value["statistical_properties"],
+        serde_json::json!(["Accuracy"])
+    );
+}
